import ballerina/io;
import ballerina/lang.value;

type Person record {|
    string name;
|};

class A {
    string got;

    function init(Person p) {
        self.got = p.name;
    }
}

class B {
    int got;

    function init(int a, int b) {
        self.got = a + b;
    }
}

public function main() returns error? {
    json j = {name: "ann"};
    A|B x = new (check value:cloneWithType(j));
    io:println(x.got); // @output ann
}
